import type { Language } from "./curriculum.ts";
import type { UntSubjectId } from "./unt-all-subjects.ts";
import type { UniversalDifficulty } from "./universal-curriculum.ts";
import type { UniversalQuestion } from "./question-engine.ts";
import type { ShynKitapExtraLessonSpec } from "./shyn-kitap-kb.ts";

function tr(ru: string, kk?: string, uz?: string): Record<Language, string> {
  return {
    ru,
    kk: kk ?? ru,
    uz: uz ?? ru
  };
}

interface QuickSingleQuestionSpec {
  idSuffix: string;
  difficulty?: UniversalDifficulty;
  prompt: [string, string, string];
  options: [[string, string, string, string], [string, string, string, string], [string, string, string, string]];
  correctIndex: 0 | 1 | 2 | 3;
  explanation: [string, string, string];
  hint: [string, string, string];
  errorCategory: string;
}

function buildLessonQuestions(
  subjectId: UntSubjectId,
  topicId: string,
  specs: [QuickSingleQuestionSpec, QuickSingleQuestionSpec, QuickSingleQuestionSpec]
): UniversalQuestion[] {
  const lessonId = `${subjectId}-lesson-${topicId}`;
  return specs.map((s, idx) => ({
    id: `${subjectId}-${topicId}-${s.idSuffix}`,
    subjectId,
    topicId,
    lessonId,
    type: "single_choice",
    difficulty: s.difficulty ?? (idx === 0 ? "basic" : idx === 1 ? "intermediate" : "advanced"),
    maxPoints: 1,
    prompt: tr(s.prompt[0], s.prompt[1], s.prompt[2]),
    options: {
      ru: [...s.options[0]],
      kk: [...s.options[1]],
      uz: [...s.options[2]]
    },
    correctIndex: s.correctIndex,
    explanation: tr(s.explanation[0], s.explanation[1], s.explanation[2]),
    hint: tr(s.hint[0], s.hint[1], s.hint[2]),
    errorCategory: s.errorCategory
  }));
}

